// Local, deterministic guidance and constrained layout proposals. No structural approval.
import {item,uid,validateProject} from './model.js';
import {canWalk} from './interior-data.js';
export const PROFILE={id:'general-vastu',version:'1.0.0',name:'General Vastu Guidance',sources:{placement:{title:'AD India — attributed residential placement guidance (2019)',url:'https://www.architecturaldigest.in/content/vastu-vastu-shashtra-vastu-tips-vastu-of-house-vastu-of-home-vastu-for-home/'},adjustments:{title:'AD India — Namrataa Kripallani on fixed layouts (2026)',url:'https://www.architecturaldigest.in/story/can-vastu-for-the-home-fix-a-difficult-layout-heres-what-you-need-to-know/'},scope:{title:'IGNCA — residential and commercial Vastu course scope',url:'https://ignca.gov.in/divisionss/academic-unit/short-term-certification-course/vastu-shastra/'}}};
export const USES=['unknown','living','bedroom','master-bedroom','kitchen','pantry','bathroom','office','shop','waiting','storage','guard','circulation','parking','stairs','lift'];
export const RULES=[
 {id:'entrance',frame:'building-centre',requires:['north','footprint','entrance'],types:['entrance'],allowed:['N','NE'],source:'placement',text:'This profile prefers a residential entrance in the north or northeast.'},
 {id:'kitchen',frame:'building-centre',requires:['north','footprint','room-use'],types:['kitchen'],allowed:['SE','NW'],source:'placement',text:'This profile prefers a kitchen in the southeast, with northwest as an alternative.'},
 {id:'bedroom',frame:'building-centre',requires:['north','footprint','room-use'],types:['bedroom','master-bedroom'],allowed:['SW'],source:'adjustments',text:'This profile prefers bedrooms in the southwest.'},
 {id:'bathroom',frame:'building-centre',requires:['north','footprint','room-use'],types:['bathroom'],allowed:['NW'],source:'placement',text:'This profile prefers bathrooms in the northwest.'},
 {id:'cooking',frame:'furniture-heading',requires:['north','cooking-facing'],types:['kitchen'],allowed:['E'],source:'placement',text:'This profile prefers the person cooking to face east.'},
 {id:'bed-head',frame:'furniture-heading',requires:['north','bed-head-facing'],types:['bedroom','master-bedroom'],avoid:['N'],source:'placement',text:'This profile advises against a bed head pointing north.'},
 {id:'living-storage',frame:'room-centre',requires:['north','heavy-furniture-position'],types:['living'],allowed:['W','SW'],source:'placement',text:'This profile prefers heavy living-room furniture toward the west or southwest.'},
 {id:'centre',frame:'building-central-ninth',requires:['footprint','confirmed-obstructions'],types:['building'],source:'adjustments',text:'This profile prefers a central area with little obstruction.'}
];
export const clone=x=>structuredClone(x);
export function fingerprint(value){let h=2166136261;for(const c of JSON.stringify(value)){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return (h>>>0).toString(16);}
export function layoutKey(f){const {blueprint,...rest}=f;return fingerprint(rest);}
export function assessmentKey(f,c){return fingerprint({layout:layoutKey(f),context:c,profile:PROFILE.version});}
export function planning(p){return p.planning||{schema:1,floors:{},briefs:{},panoramas:[]};}
export function floorRecord(p,id){return planning(p).floors[id]||{context:{occupancy:'unknown',north:{confirmed:false,degrees:0,source:''},footprint:null,entrance:null,roomUses:{},facing:{},unlockedWalls:[],budget:{amount:null,currency:'',scope:''}},alternatives:[],responses:{}};}
export function setRecord(p,id,r){p.version=2;p.planning=clone(planning(p));p.planning.floors[id]=r;}
export function approveOriginal(p,f,review){if(!review.measurements||!review.elements||!f.walls.length||!f.rooms.length)throw Error('Confirm measurements and building elements; an empty slab cannot be approved.');const r=clone(floorRecord(p,f.id));if(r.baseline)throw Error('The approved original already exists. Restore it or start another project for a new original.');r.baseline={floor:clone(f),fingerprint:layoutKey(f),approvedAt:new Date().toISOString(),review:clone(review)};r.selected='original';setRecord(p,f.id,r);}
export function direction(point,frame,north=0){const dx=point.x-frame.x-frame.w/2,dz=point.z-frame.z-frame.d/2;if(Math.hypot(dx,dz)<Math.min(frame.w,frame.d)*.08)return 'Centre';const deg=((Math.atan2(dx,-dz)*180/Math.PI-north)%360+360)%360;return ['N','NE','E','SE','S','SW','W','NW'][Math.floor((deg+22.5)/45)%8];}
function heading(degrees,north){const a=(degrees-north+3600)%360;return ['N','NE','E','SE','S','SW','W','NW'][Math.floor((a+22.5)/45)%8];}
export function assess(f,c){const findings=[],north=c.north?.confirmed&&Number.isFinite(c.north.degrees),foot=c.footprint?.confirmed;const residential=c.occupancy==='residential';
 for(const rule of RULES){const targets=rule.types.includes('building')?[{id:'building',name:'Central area'}]:rule.types.includes('entrance')?[{id:'entrance',name:'Main entrance'}]:f.rooms.filter(r=>rule.types.includes(c.roomUses?.[r.id]||'unknown')||(c.roomUses?.[r.id]||'unknown')==='unknown');
  for(const room of targets){let status='Unknown',measured='Required input is unconfirmed.',point=room.id==='entrance'?c.entrance:room.id==='building'?null:{x:room.x+room.w/2,z:room.z+room.d/2},use=c.roomUses?.[room.id]||'unknown';
   if(c.occupancy==='commercial')status='Not applicable',measured='Residential rule excluded from commercial premises.';
   else if(residential&&room.id!=='building'&&room.id!=='entrance'&&use==='unknown')measured='Confirm this room’s purpose.';
   else if(residential&&foot&&(!rule.requires.includes('north')||north)){
    if(rule.id==='centre'){if(c.obstructionsConfirmed){const b=c.footprint,centre={x:b.x+b.w/3,z:b.z+b.d/3,w:b.w/3,d:b.d/3};const obstacles=[...f.walls.map(w=>({x:Math.min(w.x1,w.x2)-w.thickness/2,z:Math.min(w.z1,w.z2)-w.thickness/2,w:Math.abs(w.x2-w.x1)+w.thickness,d:Math.abs(w.z2-w.z1)+w.thickness})),...f.items.filter(i=>i.type!=='rug').map(i=>({x:i.x-i.w/2,z:i.z-i.d/2,w:i.w,d:i.d})),...(f.features||[])];const n=obstacles.filter(o=>overlap(o,centre)).length;status=n?'Conflict':'Aligned';measured=`${n} modelled obstruction(s) intersect the central ninth.`;}}
    else if(rule.frame==='furniture-heading'){const value=c.facing?.[room.id]?.[rule.id];if(Number.isFinite(value)){measured=heading(value,c.north.degrees);status=(rule.avoid?!rule.avoid.includes(measured):rule.allowed.includes(measured))?'Aligned':'Conflict';}}
    else if(rule.id==='living-storage'){const pos=c.facing?.[room.id]?.heavy;if(pos&&Number.isFinite(pos.x)&&Number.isFinite(pos.z)){measured=direction(pos,room,c.north.degrees);status=rule.allowed.includes(measured)?'Aligned':'Conflict';}}
    else if(point&&(room.id!=='entrance'||c.entrance?.confirmed)){measured=direction(point,c.footprint,c.north.degrees);status=rule.allowed.includes(measured)?'Aligned':'Conflict';}
   }
   const finding={id:rule.id+':'+room.id,ruleId:rule.id,roomId:room.id,roomName:room.name,status,measured,point,rule:rule.text,source:PROFILE.sources[rule.source],frame:rule.frame,required:rule.requires};
   if(status==='Conflict')finding.response=remedy(rule.id,c);findings.push(finding);
  }
 }
 for(const room of f.rooms)if(!findings.some(x=>x.roomId===room.id))findings.push({id:'scope:'+room.id,ruleId:'scope',roomId:room.id,roomName:room.name,status:'Not applicable',measured:'No residential placement rule in this profile applies to the confirmed room purpose.',point:{x:room.x+room.w/2,z:room.z+room.d/2},rule:'Guidance applicability follows building and room use.',source:PROFILE.sources.scope,frame:'room-purpose',required:['room-use']});
 return {profile:PROFILE.id,version:PROFILE.version,key:assessmentKey(f,c),createdAt:new Date().toISOString(),findings};
}
export function remedy(ruleId,c){return {conflict:'The measured placement differs from the selected traditional guidance.',constraint:ruleId==='entrance'?'The footprint and entrance are fixed unless explicitly reviewed.':'Fixed services, locked structure or the permitted change policy prevent relocation.',practical:ruleId==='entrance'?'Keep required access clear and improve entrance lighting.':ruleId==='centre'?'Move movable storage out of the centre while keeping accessible paths.':'Review movable furniture, storage and lighting; consider a compatible room use only where services permit.',traditional:ruleId==='entrance'?{text:'Optional symbolic entrance motif, as discussed by Namrataa Kripallani. This is belief-based; it has no guaranteed corrective effect.',source:PROFILE.sources.adjustments}:null,limitation:'The conflicting location remains unresolved. Recording a response does not change its assessment status.'};}
export function reportStale(report,f,c){return !report||report.key!==assessmentKey(f,c)||report.version!==PROFILE.version;}
export function overlap(a,b,gap=0){return a.x<b.x+b.w-gap&&a.x+a.w>b.x+gap&&a.z<b.z+b.d-gap&&a.z+a.d>b.z+gap;}
function boxFor(i){const a=i.rotation*Math.PI/180,co=Math.abs(Math.cos(a)),si=Math.abs(Math.sin(a));return{x:i.x-(i.w*co+i.d*si)/2,z:i.z-(i.w*si+i.d*co)/2,w:i.w*co+i.d*si,d:i.w*si+i.d*co};}
function same(a,b){return JSON.stringify(a)===JSON.stringify(b);}
export function validateVariant(original,candidate,c){const errors=[];const unlocked=new Set(c.unlockedWalls||[]);const bounds=c.footprint;
 if(c.allowFurniture===false&&!same(original.items,candidate.items))errors.push('Furnishings are locked by the change policy.');
 const fixedTypes=['toilet','bath','vanity'];
 for(const i of original.items.filter(i=>i.locked||i.fixedService||fixedTypes.includes(i.type)))if(!same(i,candidate.items.find(o=>o.id===i.id)))errors.push('A locked furnishing or fixed service changed.');
 if(candidate.items.some(i=>fixedTypes.includes(i.type)&&!original.items.some(o=>o.id===i.id)))errors.push('New fixed services need explicit design review.');
 for(const key of ['id','elevation','features'])if(!same(original[key],candidate[key]))errors.push('Locked floor identity, levels or fixed features changed.');
 for(const w of original.walls){const n=candidate.walls.find(n=>n.id===w.id);if(!unlocked.has(w.id)||w.classification!=='non-structural'){if(!same(w,n))errors.push('A locked wall or opening changed: '+w.id);}else if(!n)errors.push('Partition removal requires explicit access review.');}
 if(candidate.walls.some(w=>!original.walls.some(o=>o.id===w.id)))errors.push('New walls require explicit review.');
 for(const r of original.rooms){const n=candidate.rooms.find(n=>n.id===r.id);if(!n||['x','z','w','d'].some(k=>n[k]!==r[k]))errors.push('Room boundary changes require reconstruction review.');}
 if(candidate.rooms.length!==original.rooms.length)errors.push('Room topology changed without review.');
 for(let a=0;a<candidate.rooms.length;a++)for(let b=a+1;b<candidate.rooms.length;b++)if(overlap(candidate.rooms[a],candidate.rooms[b],.03))errors.push('Room surfaces overlap.');
 for(const w of candidate.walls){const L=Math.hypot(w.x2-w.x1,w.z2-w.z1);let end=-1;for(const o of [...w.openings].sort((a,b)=>a.offset-b.offset)){if(o.offset-o.width/2<end||o.offset-o.width/2<0||o.offset+o.width/2>L)errors.push('Invalid or overlapping openings.');end=o.offset+o.width/2;}}
 const objects=candidate.items.filter(i=>!['rug','lamp'].includes(i.type));for(let n=0;n<objects.length;n++){const i=objects[n],b=boxFor(i);if(bounds&&(b.x<bounds.x||b.z<bounds.z||b.x+b.w>bounds.x+bounds.w||b.z+b.d>bounds.z+bounds.d))errors.push('Furniture exceeds footprint.');if(!candidate.rooms.some(r=>b.x>=r.x-.01&&b.z>=r.z-.01&&b.x+b.w<=r.x+r.w+.01&&b.z+b.d<=r.z+r.d+.01))errors.push('Furniture is outside a confirmed room.');
  for(const w of candidate.walls){const dx=w.x2-w.x1,dz=w.z2-w.z1,L=Math.hypot(dx,dz);for(const o of w.openings.filter(o=>o.type==='door')){const p={x:w.x1+dx*o.offset/L,z:w.z1+dz*o.offset/L};if(overlap(b,{x:p.x-.55,z:p.z-.55,w:1.1,d:1.1}))errors.push('Furniture blocks a door approach.');}const t=((i.x-w.x1)*dx+(i.z-w.z1)*dz)/(L*L);if(t>0&&t<1){const distance=Math.abs(dx*(i.z-w.z1)-dz*(i.x-w.x1))/L;const radius=(Math.abs(dz)*b.w+Math.abs(dx)*b.d)/(2*L);if(distance<radius+w.thickness/2-.02)errors.push('Furniture intersects a wall.');}}
  for(let j=n+1;j<objects.length;j++)if(overlap(b,boxFor(objects[j]),.02))errors.push('Furniture overlaps.');
 }
 if(!errors.length&&c.entrance?.confirmed&&!accessCheck(candidate,c.entrance))errors.push('Required access is blocked or cannot be established from the confirmed entrance.');
 return {valid:!errors.length,errors:[...new Set(errors)],limitations:['Access uses a 0.2 m grid and a 0.4 m diameter modelled route. Accessibility, fire egress and building-code compliance require separate review.']};}
export function accessCheck(f,entrance){if(!f.rooms.length)return false;const cell=.2,x=Math.min(...f.rooms.map(r=>r.x)),z=Math.min(...f.rooms.map(r=>r.z)),w=Math.max(...f.rooms.map(r=>r.x+r.w))-x,d=Math.max(...f.rooms.map(r=>r.z+r.d))-z,nx=Math.ceil(w/cell),nz=Math.ceil(d/cell);if(nx*nz>250000)return false;const cells=[];for(let j=0;j<nz;j++)for(let i=0;i<nx;i++){const p={x:x+(i+.5)*cell,z:z+(j+.5)*cell};const solid=[...f.items.filter(i=>!['rug','lamp'].includes(i.type)).map(boxFor),...(f.features||[]).filter(a=>['column','service','lift'].includes(a.type))];const ok=canWalk(f,p.x,p.z,.2)&&!solid.some(a=>p.x>a.x-.2&&p.x<a.x+a.w+.2&&p.z>a.z-.2&&p.z<a.z+a.d+.2);cells.push({...p,ok});}
 let start=-1,best=1.5;for(let i=0;i<cells.length;i++){const p=cells[i],distance=Math.hypot(p.x-entrance.x,p.z-entrance.z);if(p.ok&&distance<best){start=i;best=distance;}}if(start<0)return false;const seen=new Uint8Array(cells.length),q=[start];seen[start]=1;for(let n=0;n<q.length;n++){const k=q[n],i=k%nx,j=Math.floor(k/nx);for(const [di,dj]of [[1,0],[-1,0],[0,1],[0,-1]]){const ni=i+di,nj=j+dj,v=nj*nx+ni;if(ni<0||nj<0||ni>=nx||nj>=nz||seen[v]||!cells[v].ok)continue;const mid={x:(cells[k].x+cells[v].x)/2,z:(cells[k].z+cells[v].z)/2};if(!canWalk(f,mid.x,mid.z,.2))continue;seen[v]=1;q.push(v);}}
 return f.rooms.every(r=>cells.some((p,i)=>seen[i]&&p.x>r.x+.2&&p.x<r.x+r.w-.2&&p.z>r.z+.2&&p.z<r.z+r.d-.2));}
export function proposeAlternatives(f,c,instructions=''){if(!(c.budget?.amount>0)||!c.budget.currency||!['room','floor','house'].includes(c.budget.scope)||!c.entrance?.confirmed||f.rooms.some(r=>!c.roomUses?.[r.id]||c.roomUses[r.id]==='unknown'))throw Error('Confirm room uses, entrance, budget amount/currency/scope and allowed changes first.');
 const proposals=[],reasons=[],seen=new Set([layoutKey(f)]);const objectives=['Minimum change','Function and circulation','Vastu-oriented'];
 for(let k=0;k<3;k++){const v=clone(f),candidateContext=clone(c);let changed=false;const roomOrder=[...v.rooms];if(k===2&&c.north?.confirmed&&c.footprint)roomOrder.sort((a,b)=>(direction({x:a.x+a.w/2,z:a.z+a.d/2},c.footprint,c.north.degrees)==='SW'?-1:1)-(direction({x:b.x+b.w/2,z:b.z+b.d/2},c.footprint,c.north.degrees)==='SW'?-1:1));
  for(const r of roomOrder){const use=c.roomUses[r.id],type=['office','guard'].includes(use)?'desk':use==='waiting'?'chair':['bedroom','master-bedroom'].includes(use)?'bed':use==='living'?'sofa':use==='storage'?'shelf':null;if(!type)continue;
   const existing=v.items.filter(i=>i.x>=r.x&&i.x<=r.x+r.w&&i.z>=r.z&&i.z<=r.z+r.d&&i.type===type);if(existing.length&&k===0)continue;
   const positions=k===0?[[.5,.5,0]]:k===1?[[.25,.25,90],[.75,.25,0],[.5,.75,0]]:[[.75,.75,180],[.25,.75,0],[.75,.5,90]];
   if(k===2&&c.north?.confirmed&&c.occupancy==='residential'&&['bed','sofa'].includes(type)){const angle=(c.north.degrees+225)*Math.PI/180;positions.unshift([.5+Math.sin(angle)*.27,.5-Math.cos(angle)*.27,(c.north.degrees+225)%360]);}
   for(const [px,pz,rot] of positions){const trial=clone(v);const target=trial.items.find(i=>i.id===existing[0]?.id);if(target)Object.assign(target,{x:r.x+r.w*px,z:r.z+r.d*pz,rotation:rot});else trial.items.push(item(type,r.x+r.w*px,r.z+r.d*pz,rot));if(validateVariant(f,trial,c).valid){v.items=trial.items;candidateContext.facing=candidateContext.facing||{};candidateContext.facing[r.id]=candidateContext.facing[r.id]||{};if(type==='bed')candidateContext.facing[r.id]['bed-head']=rot;if(type==='sofa')candidateContext.facing[r.id].heavy={x:r.x+r.w*px,z:r.z+r.d*pz};changed=true;break;}}
   if(changed&&k===0)break;
  }
  const check=validateVariant(f,v,c),signature=layoutKey({...v,items:v.items.map(({id,...i})=>i)});if(!changed||!check.valid||seen.has(signature)){reasons.push(`${objectives[k]}: no distinct valid candidate within the fixed constraints.`);continue;}seen.add(signature);proposals.push({id:uid(),name:objectives[k],floor:v,context:candidateContext,instructions,origin:'Local constrained proposal',validation:check,assessment:assess(v,candidateContext),changes:compareLayouts(f,v),effort:'Indicative furnishing changes; no contractor quote or budget compliance claim.',createdAt:new Date().toISOString()});
 }
 return {proposals,reasons};}
export function compareLayouts(a,b){return {walls:b.walls.filter(w=>!same(w,a.walls.find(o=>o.id===w.id))).map(w=>w.id),furniture:b.items.filter(i=>!same(i,a.items.find(o=>o.id===i.id))).map(i=>i.name),removed:a.items.filter(i=>!b.items.some(o=>o.id===i.id)).map(i=>i.name),roomUses:b.rooms.filter(r=>r.name!==a.rooms.find(o=>o.id===r.id)?.name).map(r=>r.name)};}
export function applyAlternative(p,id,variant){const i=p.floors.findIndex(f=>f.id===id),record=clone(floorRecord(p,id));if(!record.baseline)throw Error('Approve the original first.');const check=validateVariant(record.baseline.floor,variant.floor,variant.context);if(!check.valid)throw Error(check.errors.join(' '));p.floors[i]=clone(variant.floor);record.selected=variant.id;record.context=clone(variant.context);record.assessment=assess(p.floors[i],record.context);record.revisions=[...(record.revisions||[]),{id:uid(),variantId:variant.id,at:new Date().toISOString()}];setRecord(p,id,record);validateProject(p);}
